<template><figure class="sheet-chart"><figcaption>{{ title }}</figcaption><canvas ref="canvas" role="img" :aria-label="title+'：'+points.map(p=>p.label+' '+p.value).join('，')"/><ul><li v-for="(point,i) in points.slice(0,12)" :key="i"><i :style="{background:colors[i%colors.length]}"/>{{ point.label }} · {{ point.value }}</li></ul></figure></template>
<script setup lang="ts">
import {onMounted,onBeforeUnmount,ref,watch} from 'vue'
const props=defineProps<{title:string;type:string;points:{label:string;value:number}[]}>(),canvas=ref<HTMLCanvasElement>()
const colors=['#3370ff','#00a870','#e4a126','#df5370','#8363c7','#169cab']
let resize:ResizeObserver|undefined
function draw(){const el=canvas.value;if(!el)return;const w=el.clientWidth,h=el.clientHeight,ratio=devicePixelRatio||1;el.width=w*ratio;el.height=h*ratio;const c=el.getContext('2d');if(!c)return;c.scale(ratio,ratio);c.clearRect(0,0,w,h);const points=props.points.slice(0,100);if(!points.length){c.fillStyle='#86909c';c.font='14px sans-serif';c.fillText('暂无可绘制数据',20,50);return}
if(props.type==='pie'){const total=points.reduce((s,p)=>s+Math.max(0,p.value),0);let angle=-Math.PI/2;points.forEach((p,i)=>{const next=angle+(total?Math.max(0,p.value)/total:0)*Math.PI*2;c.beginPath();c.moveTo(w/2,h/2);c.arc(w/2,h/2,Math.min(w,h)/2-12,angle,next);c.closePath();c.fillStyle=colors[i%colors.length]!;c.fill();angle=next});return}
const low=Math.min(0,...points.map(p=>p.value)),high=Math.max(1,...points.map(p=>p.value)),left=42,bottom=h-28,top=18,plot=w-left-16,y=(v:number)=>bottom-(v-low)/(high-low)*(bottom-top),x=(i:number)=>left+(i+.5)*plot/points.length;c.font='11px sans-serif';c.fillStyle='#86909c';c.strokeStyle='#d9dde5';c.beginPath();c.moveTo(left,top);c.lineTo(left,bottom);c.lineTo(w-10,bottom);c.stroke();c.fillText(String(high),2,top+4);c.fillText(String(low),2,bottom);points.forEach((p,i)=>{c.fillStyle=colors[i%colors.length]!;if(props.type==='bar'){const width=Math.max(2,plot/points.length*.65);c.fillRect(x(i)-width/2,Math.min(y(0),y(p.value)),width,Math.max(1,Math.abs(y(0)-y(p.value))))}else{if(props.type==='line'&&i>0){c.strokeStyle=colors[0]!;c.beginPath();c.moveTo(x(i-1),y(points[i-1]!.value));c.lineTo(x(i),y(p.value));c.stroke()}c.beginPath();c.arc(props.type==='scatter'&&Number.isFinite(Number(p.label))?left+(Number(p.label)-Math.min(...points.map(q=>Number(q.label))))/(Math.max(...points.map(q=>Number(q.label)))-Math.min(...points.map(q=>Number(q.label)))||1)*plot:x(i),y(p.value),4,0,Math.PI*2);c.fill()}if(points.length<=12){c.fillStyle='#686f7a';c.fillText(p.label.slice(0,7),x(i)-15,h-8)}})}
watch(()=>[props.points,props.type],draw,{deep:true});onMounted(()=>{resize=new ResizeObserver(draw);resize.observe(canvas.value!);draw()});onBeforeUnmount(()=>resize?.disconnect())
</script>
<style scoped>.sheet-chart{margin:0;min-width:0}.sheet-chart figcaption{font-size:var(--text-body);font-weight:600;margin-bottom:var(--space-2);overflow-wrap:anywhere}.sheet-chart canvas{width:100%;height:220px;display:block}.sheet-chart ul{padding:0;list-style:none;display:flex;flex-wrap:wrap;gap:8px;font-size:12px;color:var(--c-text-secondary)}.sheet-chart li{display:flex;gap:5px;align-items:center}.sheet-chart i{width:8px;height:8px;border-radius:2px}</style>
